with unpacked as (select id, customer_id, created_at, items, ship_to, attributes['device'] as device, exists(items, i -> i.price > 100) as has_premium_item, attributes['gift'] as gift, size(filter(items, i -> i.qty >= 3)) as bulk_lines from carts) select id, customer_id, has_premium_item, gift, bulk_lines, lead(bulk_lines, 1) over (partition by customer_id order by bulk_lines, id) as next_bulk_lines, sum(bulk_lines) over (partition by customer_id order by cast(created_at as bigint) range between 1800 preceding and current row) as bulk_lines_sum_30m, row_number() over (order by created_at, id) as event_seq from unpacked
